const cfg = $('Params').first().json;
const same = (a, b) => { if (a === b) return true; try { return JSON.stringify(typeof a === 'string' ? JSON.parse(a) : a) === JSON.stringify(typeof b === 'string' ? JSON.parse(b) : b); } catch (e) { return false; } };
const live = {}; const ldesc = {}; for (const k of ($('Get Current').first().json.keys || [])) { if (k.is_archived) continue; ldesc[k.key_id] = String(k.description || ''); for (const t of (k.translations||[])) live[k.key_id + '|' + t.language_iso] = t.translation; }
const per = {}; const held = [];
for (const [id, iso, oldT, newT] of cfg.F) { const l = live[id + '|' + iso]; if (!same(l, oldT)) { held.push([id, iso, 'changed since read']); continue; } const tr = { language_iso: iso, translation: newT, is_unverified: true }; if (cfg.status) tr.custom_translation_status_ids = [cfg.status]; (per[id] = per[id] || []).push(tr); }
const descOut = {}; for (const id in (cfg.descs || {})) { if (ldesc[id] === undefined) { held.push([id, 'desc', 'key missing/archived']); continue; } if (ldesc[id].trim()) { held.push([id, 'desc', 'description exists']); continue; } descOut[id] = cfg.descs[id]; }
const allIds = Array.from(new Set(Object.keys(per).concat(Object.keys(descOut))));
let keys = allIds.map(id => { const k = { key_id: Number(id) }; if (per[id]) k.translations = per[id]; if (descOut[id] !== undefined) k.description = descOut[id]; return k; });
if (cfg.mode === 'one') keys = keys.slice(0, 1);
const out = []; for (let i = 0; i < keys.length; i += 40) out.push({ json: { body: { keys: keys.slice(i, i + 40) }, n: keys.slice(i, i + 40).reduce((a, k) => a + (k.translations || []).length, 0), descs: keys.slice(i, i + 40).filter(k => k.description !== undefined).length, held } });
if (!out.length) throw new Error('nothing to write: ' + JSON.stringify(held.slice(0, 20)));
return out;

const cfg = $('Params').first().json;
const same = (a, b) => { if (a === b) return true; try { return JSON.stringify(typeof a === 'string' ? JSON.parse(a) : a) === JSON.stringify(typeof b === 'string' ? JSON.parse(b) : b); } catch (e) { return false; } };
const live = {}; const ldesc = {}; for (const k of ($('Read Back').first().json.keys || [])) { ldesc[k.key_id] = String(k.description || ''); for (const t of (k.translations||[])) live[k.key_id + '|' + t.language_iso] = t; }
let fixed = 0, unver = 0, status = 0; const notFixed = [];
for (const [id, iso, oldT, newT] of cfg.F) { const t = live[id + '|' + iso] || {}; if (same(t.translation, newT)) { fixed++; if (t.is_unverified) unver++; if ((t.custom_translation_statuses || []).some(s => s.status_id === cfg.status)) status++; } else notFixed.push([id, iso, t.translation]); }
let descOk = 0; const descBad = []; for (const id in (cfg.descs || {})) { if (ldesc[id] === cfg.descs[id]) descOk++; else descBad.push([id, ldesc[id].slice(0, 80)]); }
const b = $('Build').all();
return [{ json: { sent: b.reduce((a, i) => a + i.json.n, 0), descsSent: b.reduce((a, i) => a + (i.json.descs || 0), 0), held: b[0].json.held, fixedNow: fixed, unverified: unver, withStatus: status, notFixed, descOk, descBad } }];
